"use client";

import React, { useMemo, useState } from "react";
import NavbarMenu from "../components/NavMenu";
import {
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
  BarChart, Bar, PieChart, Pie, Cell,
} from "recharts";

export default function StatisticsPage() {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const mockHistoryData = [
    { name: "Sản phẩm A", href: "/san-pham-a" },
    { name: "Tin tức mới nhất", href: "/tin-tuc" },
  ];

  const [range, setRange] = useState<string>("7d");
  const [model, setModel] = useState<string>("all");

  const mockTotals = useMemo(() => ({ users: 128, questions: 452, answers: 936, todayNew: 12 }), []);
  const mockDaily = useMemo(() => {
    const days = range === "7d" ? 7 : range === "14d" ? 14 : 30;
    const today = new Date();
    return Array.from({ length: days }).map((_, i) => {
      const d = new Date(today);
      d.setDate(today.getDate() - (days - 1 - i));
      const date = d.toISOString().slice(0, 10);
      const bias = model === "all" ? 1 : model === "gpt-5" ? 1.2 : 0.9;
      return {
        date,
        questions: Math.floor((20 + Math.random() * 30) * bias),
        answers: Math.floor((30 + Math.random() * 40) * bias),
      };
    });
  }, [range, model]);

  const mockByModel = useMemo(() => [
    { name: "gpt-4o-mini", count: 320 },
    { name: "gpt-5", count: 210 },
    { name: "local-llm", count: 58 },
  ], []);

  const mockByTag = useMemo(() => [
    { name: "Next.js", count: 180 },
    { name: "DB/SQL", count: 140 },
    { name: "Arduino/IoT", count: 90 },
    { name: "UX/UI", count: 42 },
  ], []);

  const COLORS = ["#8884d8", "#82ca9d", "#ffc658", "#ff8042", "#8dd1e1"];

  return (
    <>
      <style jsx>{`
        @keyframes gradientShift {
          0% { background-position: 0% 50%; }
          50% { background-position: 100% 50%; }
          100% { background-position: 0% 50%; }
        }
        .gradient-bg {
          background: linear-gradient(45deg, #8DBCC7, #A4CCD9, #EBFFD8, #38f9d7);
          background-size: 400% 400%;
          animation: gradientShift 15s ease infinite;
        }
      `}</style>

      <main className="gradient-bg min-h-screen overflow-x-hidden pt-16">
        <NavbarMenu
          isMenuOpen={isMenuOpen}
          onMenuClick={() => setIsMenuOpen(!isMenuOpen)}
          onClose={() => setIsMenuOpen(false)}
          historyItems={mockHistoryData}
        />

        <div className="max-w-7xl mx-auto px-6 md:px-8 pb-16">
          <div className="mb-6 flex items-start justify-between gap-4 flex-wrap">
            <div>
              <h1 className="text-2xl md:text-3xl font-bold">Bảng điều khiển thống kê</h1>
              <p className="text-gray-700/90">Frontend-only • Dùng mock data • Dễ thay bằng API thật sau này.</p>
            </div>
            <Toolbar range={range} setRange={setRange} model={model} setModel={setModel} />
          </div>

          <section className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">
            <StatCard label="Người dùng" value={mockTotals.users} />
            <StatCard label="Câu hỏi" value={mockTotals.questions} />
            <StatCard label="Câu trả lời" value={mockTotals.answers} />
            <StatCard label="Mới hôm nay" value={mockTotals.todayNew} />
          </section>

          <section className="grid grid-cols-1 xl:grid-cols-2 gap-8">
            <ChartCard title="Lưu lượng theo ngày">
              <div className="h-72">
                <ResponsiveContainer width="100%" height="100%">
                  <LineChart data={mockDaily}>
                    <CartesianGrid strokeDasharray="3 3" />
                    <XAxis dataKey="date" />
                    <YAxis />
                    <Tooltip />
                    <Legend />
                    <Line type="monotone" dataKey="questions" name="Câu hỏi" stroke="#8884d8" strokeWidth={2} />
                    <Line type="monotone" dataKey="answers" name="Câu trả lời" stroke="#82ca9d" strokeWidth={2} />
                  </LineChart>
                </ResponsiveContainer>
              </div>
            </ChartCard>

            <ChartCard title="Phân bố theo Model">
              <div className="h-72">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={mockByModel}>
                    <CartesianGrid strokeDasharray="3 3" />
                    <XAxis dataKey="name" />
                    <YAxis />
                    <Tooltip />
                    <Legend />
                    <Bar dataKey="count" name="Số lượt" fill="#8884d8" radius={[8, 8, 0, 0]} />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </ChartCard>

            <ChartCard title="Tỉ lệ theo Tag/Chủ đề" className="xl:col-span-2">
              <div className="h-80 overflow-visible">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart margin={{ top: 16, right: 24, bottom: 40, left: 24 }}>
                    <Pie
                      data={mockByTag}
                      dataKey="count"
                      nameKey="name"
                      cx="50%"
                      cy="45%"
                      outerRadius={110}
                      labelLine={false}
                      label={(entry: { name?: string; percent?: number }) =>
                        `${entry.name ?? ""} ${(((entry.percent ?? 0) * 100).toFixed(0))}%`
                      }
                    >
                      {mockByTag.map((_, i) => (
                        <Cell key={i} fill={COLORS[i % COLORS.length]} />
                      ))}
                    </Pie>
                    <Tooltip />
                    <Legend verticalAlign="bottom" height={32} />
                  </PieChart>
                </ResponsiveContainer>
              </div>
            </ChartCard>
          </section>
        </div>
      </main>
    </>
  );
}

function Toolbar({ range, setRange, model, setModel }: { range: string; setRange: (v: string) => void; model: string; setModel: (v: string) => void; }) {
  return (
    <div className="flex items-center gap-2 bg-white/80 backdrop-blur border rounded-2xl shadow p-2">
      <Select
        label="Khoảng thời gian"
        value={range}
        onChange={(e) => setRange(e.target.value)}
        options={[{ value: "7d", label: "7 ngày" }, { value: "14d", label: "14 ngày" }, { value: "30d", label: "30 ngày" }]}
      />
      <div className="w-px h-6 bg-gray-200" />
      <Select
        label="Model"
        value={model}
        onChange={(e) => setModel(e.target.value)}
        options={[{ value: "all", label: "Tất cả" }, { value: "gpt-5", label: "gpt-5" }, { value: "gpt-4o-mini", label: "gpt-4o-mini" }, { value: "local-llm", label: "local-llm" }]}
      />
      <button className="ml-1 px-3 py-2 text-sm rounded-xl bg-gray-900 text-white hover:opacity-90 active:scale-[.98]">
        Áp dụng
      </button>
    </div>
  );
}

function Select({ label, value, onChange, options }: { label: string; value: string; onChange: React.ChangeEventHandler<HTMLSelectElement>; options: Array<{ value: string; label: string }>; }) {
  return (
    <label className="flex items-center gap-2 text-sm">
      <span className="text-gray-600 whitespace-nowrap">{label}</span>
      <select className="px-3 py-2 rounded-xl border bg-white hover:bg-gray-50" value={value} onChange={onChange}>
        {options.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}
      </select>
    </label>
  );
}

function StatCard({ label, value }: { label: string; value: number }) {
  return (
    <div className="bg-white rounded-2xl shadow p-4">
      <div className="text-sm text-gray-500">{label}</div>
      <div className="text-2xl md:text-3xl font-bold mt-1">{value}</div>
    </div>
  );
}

function ChartCard({ title, className, children }: { title: string; className?: string; children: React.ReactNode; }) {
  return (
    <div className={`bg-white rounded-2xl shadow p-4 ${className ?? ""}`}>
      <div className="flex items-center justify-between mb-3">
        <h2 className="font-semibold">{title}</h2>
        <div className="text-xs text-gray-400">mock data</div>
      </div>
      {children}
    </div>
  );
}
